/**
 * MACHINE-READABLE error-code map — P1 output, consumed by P2/P3.
 *
 * Generated by the P1 harvest/triage (analysis only). Maps every legacy
 * snake_case domain code (as thrown today in `code:` or `message:`) to its
 * proposed canonical `AppErrorCode`, tier, HTTP category, and disposition.
 *
 * ⚠️ NOT YET WIRED. This is a proposal pending sign-off on the NEEDS_DECISION
 * rows (see error-code-registry.md). P2 folds the canonical set into
 * `packages/errors/src/codes.ts`; P3 rewrites throw sites using this map.
 * `httpCategory` for KEEP rows is heuristic-inferred and must be reviewed.
 */

export type Tier = "user-facing" | "internal";
export type HttpCategory =
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "UNAUTHORIZED"
  | "CONFLICT"
  | "INVALID_INPUT"
  | "PRECONDITION_FAILED"
  | "RATE_LIMITED"
  | "INTERNAL_SERVER_ERROR";

export type Disposition =
  | "KEEP"
  | "INTERNAL"
  | "NEEDS_DECISION"
  | `COLLAPSE→${string}`;

export interface ErrorCodeEntry {
  /** Proposed canonical SCREAMING_SNAKE AppErrorCode. */
  canonical: string;
  tier: Tier;
  httpCategory: HttpCategory;
  disposition: Disposition;
  /** Specificity preserved on the wire when this code collapses into another. */
  meta?: Record<string, unknown>;
  /** Which field the legacy code was thrown in: code | message | both. */
  field: "code" | "message" | "both";
  /** Occurrence count across use-cases + ports (throw sites). */
  count: number;
}

